command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="eccc723ce730b49be79626cf2e5794d1e2a9fabc"
$candidate="b137a9f7f6882dbd7dddc43953dc0fcdb2b6e624"
$branch="work/metadata-sort-baseline-harness-20261006"
$temp=Join-Path $env:RUNNER_TEMP ("fly-metadata-baseline-"+$env:GITHUB_RUN_ID)
$cache="C:\dev\flyExplorer\logs\metadata-sort-baseline-runtime-"+$candidate.Substring(0,8)
$evidence=Join-Path $repo "logs\remote-evidence"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "metadata baseline fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before metadata baseline"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "metadata baseline branch moved"}
& git diff --quiet ($main+"..."+$candidate) -- app/winui src/base build.bat run.bat
if($LASTEXITCODE -ne 0){throw "baseline harness branch changed product files"}
& git worktree add --detach $temp $candidate
if($LASTEXITCODE -ne 0){throw "metadata baseline worktree creation failed"}
try{
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "metadata baseline diff check failed"}
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "metadata baseline Release build failed"}
  Write-Host "METADATA_SORT_BASELINE_RELEASE_BUILD=PASS"
  if(Test-Path -LiteralPath $cache){Remove-Item -LiteralPath $cache -Recurse -Force}
  New-Item -ItemType Directory -Path $cache -Force | Out-Null
  Copy-Item -Path (Join-Path $temp "out\winui\Release\*") -Destination $cache -Recurse -Force
  if(!(Test-Path -LiteralPath (Join-Path $cache "flyExplorer.exe"))){throw "metadata baseline runtime cache missing executable"}
  Write-Host ("METADATA_SORT_BASELINE_RUNTIME_CACHE="+$cache)
  & python -X utf8 tests\winui\test_metadata_sort_gui.py --configuration Release --expect-legacy-fallback --capture before
  if($LASTEXITCODE -ne 0){throw "metadata baseline GUI failed"}
  Write-Host "METADATA_SORT_BASELINE_GUI=PASS"
  New-Item -ItemType Directory -Path $evidence -Force | Out-Null
  Copy-Item -LiteralPath (Join-Path $temp "logs\metadata-sort\metadata-sort-before.png") -Destination (Join-Path $evidence "metadata-sort-before.png") -Force
  Write-Host "METADATA_SORT_BASELINE_VISUAL=EXPORTED"
} finally {
  Set-Location -LiteralPath $repo
  & git worktree remove $temp --force
}
